import csv, json
from pathlib import Path
csv_path=Path('/app/data/bank_transactions.csv')
json_path=Path('/app/data/output.json')
allowed_accounts={'BUS-30001','BUS-30999','BUS-35001'}
allowed_names={'North West Capital Group Incorporated','North West Capital Group Incoporated','NWCG Inc. Pty. Ltd.'}
with csv_path.open(newline='', encoding='utf-8') as f:
    rows=list(csv.DictReader(f))
expected=[]
for n,r in enumerate(rows,2):
    if r['Account Number'] in allowed_accounts or r['Company Name'] in allowed_names:
        expected.append((n,r))
with json_path.open(encoding='utf-8') as f:
    data=json.load(f)
actual={(tuple(o.items())) for o in data}
print('expected count',len(expected))
for n,r in sorted(expected, key=lambda x:x[1]['Date']):
    marker='OK' if tuple(r.items()) in actual else 'MISSING'
    print(marker,n,r)
PY"}

